CREATE TABLE `attrition_model_profiles` (
	`employee_id` text PRIMARY KEY NOT NULL,
	`observed_attrition` text NOT NULL,
	`risk_score` real NOT NULL,
	`risk_level` text NOT NULL,
	`top_driver` text NOT NULL,
	`monthly_income` real NOT NULL,
	`distance_from_home` integer NOT NULL,
	`education_level` integer NOT NULL,
	`education_field` text NOT NULL,
	`environment_satisfaction` integer NOT NULL,
	`job_satisfaction` integer NOT NULL,
	`prior_companies` integer NOT NULL,
	`work_life_balance` integer NOT NULL,
	`years_at_company` real NOT NULL,
	`model_version` text NOT NULL,
	`data_source` text DEFAULT 'demo' NOT NULL,
	`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
--> statement-breakpoint
CREATE INDEX `attrition_model_risk_idx` ON `attrition_model_profiles` (`risk_level`,`risk_score`);--> statement-breakpoint
CREATE INDEX `attrition_model_observed_idx` ON `attrition_model_profiles` (`observed_attrition`);
